              logic: () => o.UserID === userid,
              description: "o.UserID=userid",
            }).build().pass,
        ),
      description: "User.allInstance()->any(o|o.UserID=userid)",
    }).build().pass;
    let newCreated: boolean = l({
      logic: () => StandardOPs.oclIsUndefined(u),
      description: "u.oclIsUndefined()",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsTypeOf(userid, Integer),
        description: "userid.oclIsTypeOf(Integer)",
      })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(name, String),
          description: "name.oclIsTypeOf(String)",
        })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(address, String),
          description: "address.oclIsTypeOf(String)",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let newUser: User;
    return l({
      execute: () => (newUser = new User()),
      description: "newUser.oclIsNew()",
    })
      .and({
        execute: () => (newCreated = true),
        description: "newCreated=true",
      })
      .and({
        execute: () => (newUser.UserID = userid),
        description: "newUser.UserID=userid",
      })
      .and({
        execute: () => (newUser.Name = name),
        description: "newUser.Name=name",
      })
      .and({
        execute: () => (newUser.Address = address),
        description: "newUser.Address=address",
      })
      .and({
        execute: () => getRepository(User).push(newUser),
        description: "User.allInstance()->includes(newUser)",
      })
      .or({
        execute: () => (u.UserID = userid),
        description: "u.UserID=userid",
      })
      .and({
        execute: () => (u.Name = name),
        description: "u.Name=name",
      })
      .and({
        execute: () => (u.Address = address),
        description: "u.Address=address",
      })
      .and({
        execute: () => getRepository(User).push(u),
        description: "User.allInstance()->includes(u)",
      })
      .and({
        execute: () => (newCreated = false),
        description: "newCreated=false",
      })
      .and({
        execute: () => newCreated,
        description: "result=newCreated",
      })
      .build().value;
    /*Postcondition End*/
  }
}
